'use client';

import { useGLTF } from '@react-three/drei';
import * as THREE from 'three';

type DoorMaterialsGLTF = {
  materials: {
    RAL1013MATT: THREE.MeshStandardMaterial;
    RAL3004MATT: THREE.MeshStandardMaterial;
    RAL5003MATT: THREE.MeshStandardMaterial;
    RAL6005MATT: THREE.MeshStandardMaterial;
  };
};

/**
 * Hook to access the door materials from the loaded GLB file
 * Returns the materials object with all 4 RAL colors
 */
export function useDoorMaterials() {
  const { materials } = useGLTF(
    '/materials/door-materials.glb',
  ) as unknown as DoorMaterialsGLTF;
  return materials;
}

/**
 * Hook to get a specific material by ID
 */
export function useDoorMaterial(materialId?: string) {
  const materials = useDoorMaterials();

  if (!materialId) return null;

  // Map your material IDs to the actual material names
  const materialMap: Record<string, keyof typeof materials> = {
    'ral-1013': 'RAL1013MATT',
    'ral-3004': 'RAL3004MATT',
    'ral-5003': 'RAL5003MATT',
    'ral-6005': 'RAL6005MATT',
  };

  const materialKey = materialMap[materialId];
  return materialKey ? materials[materialKey] : null;
}

// Preload the materials
useGLTF.preload('/materials/door-materials.glb');

