'use client';

import { useMemo } from 'react';
import * as THREE from 'three';
import { useDoorMaterial } from '../../hooks/useDoorMaterials';

// Frame dimensions in meters
const FRAME_PROFILE_WIDTH = 0.066; // 66mm frame profile width (sides and top)
const FRAME_PROFILE_WIDTH_BOTTOM = 0.03; // 30mm frame profile width (bottom/threshold)
const FRAME_PROFILE_DEPTH = 0.08; // 8cm frame profile depth

interface ParametricFrameProps {
  doorWidth: number; // inner door width in meters
  doorHeight: number; // inner door height in meters
  frameWidth?: number; // frame profile width
  frameDepth?: number; // frame profile depth
  color?: string;
  // Optional: Use material ID to load RAL material from Blender
  materialId?: string;
  position?: [number, number, number];
}

/**
 * Creates a door frame using box geometries.
 * The frame only surrounds the door panel itself (not glass panels).
 * Glass panels have their own separate frames.
 * All dimensions in meters.
 */
export const ParametricFrame: React.FC<ParametricFrameProps> = ({
  doorWidth,
  doorHeight,
  frameWidth = FRAME_PROFILE_WIDTH,
  frameDepth = FRAME_PROFILE_DEPTH,
  color = '#895129',
  materialId,
  position = [0, 0, 0],
}) => {
  // Load Blender material if materialId is provided
  const blenderMaterial = useDoorMaterial(materialId);
  // Frame only surrounds the door panel (doorWidth x doorHeight)
  // Note: bottom frame uses narrower width (30mm) than sides/top (66mm)
  const outerWidth = doorWidth + frameWidth * 2;

  // Create frame pieces as box geometries (only around door panel)
  const frameGeometries = useMemo(() => {
    const pieces: {
      geometry: THREE.BoxGeometry;
      position: [number, number, number];
    }[] = [];

    // Bottom frame piece (threshold) - uses narrower width (30mm)
    const bottomFrameWidth = FRAME_PROFILE_WIDTH_BOTTOM;
    pieces.push({
      geometry: new THREE.BoxGeometry(outerWidth, bottomFrameWidth, frameDepth),
      position: [0, -doorHeight / 2 - bottomFrameWidth / 2, 0],
    });

    // Top frame piece - 66mm
    pieces.push({
      geometry: new THREE.BoxGeometry(outerWidth, frameWidth, frameDepth),
      position: [0, doorHeight / 2 + frameWidth / 2, 0],
    });

    // Left frame piece - 66mm
    pieces.push({
      geometry: new THREE.BoxGeometry(frameWidth, doorHeight, frameDepth),
      position: [-doorWidth / 2 - frameWidth / 2, 0, 0],
    });

    // Right frame piece - 66mm
    pieces.push({
      geometry: new THREE.BoxGeometry(frameWidth, doorHeight, frameDepth),
      position: [doorWidth / 2 + frameWidth / 2, 0, 0],
    });

    return pieces;
  }, [outerWidth, doorWidth, doorHeight, frameWidth, frameDepth]);

  return (
    <group position={position}>
      {frameGeometries.map((piece, index) => (
        <mesh
          key={index}
          geometry={piece.geometry}
          position={piece.position}
          castShadow
          receiveShadow>
          {blenderMaterial ? (
            <primitive object={blenderMaterial} attach="material" />
          ) : (
            <meshStandardMaterial color={color} />
          )}
        </mesh>
      ))}
    </group>
  );
};

